package tn.smartuniversity.assistant;
import java.util.*; import org.springframework.data.mongodb.core.MongoTemplate; import org.springframework.data.mongodb.core.query.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/assistant") public class AssistantController {private final MongoTemplate db;public AssistantController(MongoTemplate d){db=d;}public record Ask(String question){}public record Answer(String answer,List<String> sources){} @PostMapping("/ask") public Answer ask(@RequestBody Ask ask){String q=ask.question()==null?"":ask.question().trim();if(q.isBlank())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Question is required");String[] terms=q.toLowerCase().split("\\W+");List<Map> docs=db.find(new Query().limit(100),Map.class,"course-materials");List<Map> relevant=docs.stream().filter(d->{String content=(Objects.toString(d.get("title"),"")+" "+Objects.toString(d.get("content"),"")).toLowerCase();return Arrays.stream(terms).filter(t->t.length()>3).anyMatch(content::contains);}).limit(3).toList();if(relevant.isEmpty())return new Answer("I could not find a relevant answer in the university resources currently indexed. Try rephrasing your question or ask your professor.",List.of());StringBuilder out=new StringBuilder("I found the following information in the available university resources:\n\n");List<String> sources=new ArrayList<>();for(Map d:relevant){out.append("• ").append(Objects.toString(d.get("title"),"Course resource")).append(": ").append(Objects.toString(d.get("content"),"")).append("\n\n");sources.add(Objects.toString(d.get("title"),"Course resource"));}out.append("This answer is based on indexed course material. Please verify important academic or administrative decisions with the relevant university office.");return new Answer(out.toString(),sources);} }
